<?php namespace App\Providers;use Illuminate\Support\ServiceProvider;use Illuminate\Support\Facades\RateLimiter;use Illuminate\Cache\RateLimiting\Limit;use Illuminate\Http\Request;
class AppServiceProvider extends ServiceProvider{public function register():void{$this->app->bind(\App\Features\Stock\Contracts\StockRepositoryInterface::class,\App\Features\Stock\Repositories\StockRepository::class);}public function boot():void{if(config('app.force_https'))\Illuminate\Support\Facades\URL::forceScheme('https');RateLimiter::for('global',fn(Request $r)=>Limit::perSecond(1000)->by($r->user()?->id?:$r->ip()));}}
